import { Fragment, useEffect, useState } from "react";
import "./App.css";
import Stopwatch from "./Stopwatch.tsx";
import React from "react";

function App() {
  // const [time, setTime] = useState(0);

  const [runningGender, setRunningGender] = useState();

  const startGender = (genderId) => {
    setRunningGender(genderId);
  };

  const [genders, setGenders] = useState([
    { id: "m", display: "Homme", time: 0, running: false },
    { id: "f", display: "Femme", time: 0, running: false },
    { id: "nb", display: "Non-Binaire", time: 0, running: false },
  ]);
  useEffect(() => {
    let interval;
    if (runningGender) {
      interval = setInterval(() => {
        setGenders(
          (prevState) =>
            prevState?.find((gender) => gender.id === runningGender).time + 10
        );
        (prevTime) => prevTime + 10;
      }, 10);
    } else if (!runningGender) {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [runningGender]);

  return (
    <div className="App">
      {genders.map((gender) => (
        <Fragment>
          <Stopwatch
            display={gender.display}
            key={gender.id}
            time={gender.time}
            // running={genders[gender].running}
          />
          <button onClick={() => startGender(gender.id)}>
            Start {gender.display}
          </button>
        </Fragment>
      ))}
    </div>
  );
}

export default App;
